CREATE TABLE tax_rule (id VARCHAR(100) NOT NULL, version VARCHAR(32) NOT NULL, valid_from TIMESTAMPTZ NOT NULL, valid_until TIMESTAMPTZ, rate NUMERIC(12,10) NOT NULL CHECK(rate BETWEEN 0 AND 1), legal_basis TEXT NOT NULL, author_id VARCHAR(100) NOT NULL, approver_id VARCHAR(100), status VARCHAR(16) NOT NULL, PRIMARY KEY(id,version), CHECK(status <> 'APPROVED' OR (approver_id IS NOT NULL AND approver_id <> author_id)));
CREATE TABLE tax_calculation (id UUID PRIMARY KEY, tenant_id UUID NOT NULL, transaction_id VARCHAR(100) NOT NULL, rule_id VARCHAR(100) NOT NULL, rule_version VARCHAR(32) NOT NULL, base_amount NUMERIC(20,2) NOT NULL, tax_amount NUMERIC(20,2) NOT NULL, occurred_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,transaction_id));
CREATE TABLE calculation_memory (calculation_id UUID NOT NULL REFERENCES tax_calculation(id), line_no INTEGER NOT NULL, expression TEXT NOT NULL, value NUMERIC(20,2) NOT NULL, PRIMARY KEY(calculation_id,line_no));
CREATE TABLE outbox_event (event_id UUID PRIMARY KEY, tenant_id UUID NOT NULL, aggregate_id VARCHAR(100) NOT NULL, event_type VARCHAR(100) NOT NULL, schema_version VARCHAR(16) NOT NULL, payload JSONB NOT NULL, occurred_at TIMESTAMPTZ NOT NULL, published_at TIMESTAMPTZ);
CREATE INDEX outbox_unpublished_idx ON outbox_event(occurred_at) WHERE published_at IS NULL;
